<script setup lang="ts">
import { inject, onBeforeUnmount, onMounted, ref, watch, type Ref } from 'vue';
import { onBeforeRouteLeave } from 'vue-router';
import { api, command, displayTime, errorMessage, request, today, type Department } from '@worktime/api-client';
import ModalShell from '../../shared/ModalShell.vue';
interface Manager{id:string;departmentId:string;departmentName:string;userId:string;userName:string;title:string;effectiveFrom:string;effectiveTo:string|null;revokedAt:string|null;active:boolean;canRevoke:boolean}
interface Grant{id:string;userId:string;role:string;scopeType:string;departmentId:string|null;departmentName:string|null;effectiveFrom:string;effectiveTo:string|null;revokedAt:string|null;active:boolean;canRevoke:boolean}
interface History{userId:string;departments:{id:string;departmentId:string;departmentName:string;effectiveFrom:string;effectiveTo:string|null}[];levels:{id:string;level:string;effectiveFrom:string;effectiveTo:string|null}[];enrollments:{id:string;effectiveFrom:string;effectiveTo:string|null;voided:boolean}[]}
const busy=ref(false),error=ref(''),notice=ref(''),tab=ref('managers'),users=ref<{id:string;employeeNo:string;name:string}[]>([]),departments=ref<Department[]>([]),departmentId=ref(''),userId=ref(''),managers=ref<Manager[]>([]),grants=ref<Grant[]>([]),history=ref<History>();
const modal=ref(''),targetId=ref(''),reason=ref(''),person=ref(''),title=ref('HEAD'),role=ref('LEADER'),scopeType=ref('DEPARTMENT'),scopeDepartment=ref(''),from=ref(today()),to=ref('');const sharedBusy=inject<Ref<boolean>>('operationBusy');watch(busy,v=>{if(sharedBusy)sharedBusy.value=v;});
const roles:Record<string,string>={EMPLOYEE:'员工',ADMIN:'管理员',PM:'项目经理',DEPARTMENT_MANAGER:'部门负责人',LEADER:'公司领导'};
async function load(){busy.value=true;error.value='';try{if(tab.value==='managers'&&departmentId.value)managers.value=await request(`/master/departments/${departmentId.value}/managers`);if(tab.value==='grants'&&userId.value)grants.value=await request(`/master/users/${userId.value}/grants`);if(tab.value==='history'&&userId.value)history.value=await request(`/master/users/${userId.value}/history`);}catch(e){error.value=errorMessage(e);}finally{busy.value=false;}}
async function changeTab(value:string){if(busy.value)return;tab.value=value;await load();}
function open(value:string,id=''){modal.value=value;targetId.value=id;reason.value='';person.value='';title.value='HEAD';role.value='LEADER';scopeType.value='DEPARTMENT';scopeDepartment.value=departmentId.value;from.value=today();to.value='';error.value='';}
function changeRole(){scopeType.value=role.value==='DEPARTMENT_MANAGER'?'DEPARTMENT':role.value==='LEADER'?scopeType.value:'COMPANY';}
async function commit(){busy.value=true;error.value='';try{if(modal.value==='manager')await command(`/master/departments/${departmentId.value}/managers`,{userId:person.value,title:title.value,effectiveFrom:from.value,effectiveTo:to.value||null,reason:reason.value});if(modal.value==='grant')await command(`/master/users/${userId.value}/grants`,{role:role.value,scopeType:scopeType.value,departmentId:scopeType.value==='DEPARTMENT'?scopeDepartment.value:null,effectiveFrom:from.value,effectiveTo:to.value||null,reason:reason.value});if(modal.value==='revokeManager')await command(`/master/department-managers/${targetId.value}/revoke`,{reason:reason.value});if(modal.value==='revokeGrant')await command(`/master/role-grants/${targetId.value}/revoke`,{reason:reason.value});modal.value='';notice.value='范围变更已登记，当前权限以有效任职与授权的合计范围为准。';await load();}catch(e){error.value=errorMessage(e);}finally{busy.value=false;}}
onMounted(async()=>{busy.value=true;try{[users.value,departments.value]=await Promise.all([api.list<{id:string;employeeNo:string;name:string}>('users'),api.list<Department>('departments')]);departmentId.value=departments.value[0]?.id??'';userId.value=users.value[0]?.id??'';await load();}catch(e){error.value=errorMessage(e);}finally{busy.value=false;}});onBeforeRouteLeave(()=>!busy.value&&(!modal.value||!reason.value||window.confirm('授权说明尚未提交，确定离开？')));onBeforeUnmount(()=>{if(sharedBusy)sharedBusy.value=false;});
</script>
<template><div class="workflow-page"><div class="workflow-head"><div><h1>负责人与权限范围</h1><p>按有效期登记多位正副职、独立授权范围与人员历史。</p></div><RouterLink to="/people">返回人员与组织</RouterLink></div><nav class="workflow-tabs"><button v-for="t in [{id:'managers',name:'部门正副职'},{id:'grants',name:'角色范围授权'},{id:'history',name:'人员历史'}]" :key="t.id" :class="{active:tab===t.id}" :disabled="busy" @click="changeTab(t.id)">{{ t.name }}</button></nav><div class="workflow-filters"><label v-if="tab==='managers'">管理部门<select aria-label="管理部门" v-model="departmentId" :disabled="busy" @change="load"><option v-for="d in departments" :key="d.id" :value="d.id">{{ d.name }}</option></select></label><label v-else>选择人员<select aria-label="选择人员" v-model="userId" :disabled="busy" @change="load"><option v-for="u in users" :key="u.id" :value="u.id">{{ u.name }} / {{ u.employeeNo }}</option></select></label><button :disabled="busy" @click="load">刷新</button><button v-if="tab!=='history'" class="primary" :disabled="busy||!departmentId||!userId" @click="open(tab==='managers'?'manager':'grant')">{{ tab==='managers'?'新增任职':'新增范围授权' }}</button></div><p v-if="error" class="workflow-error" role="alert">{{ error }}</p><p v-if="notice" class="workflow-success">{{ notice }}</p><p class="workflow-note">有效期包含开始日，不包含结束日。撤销即时生效；其他仍有效的任职或授权继续有效。</p><template v-if="tab==='managers'"><p class="workflow-note">同部门可有多名正副职，管理范围包含子部门。部门的“默认负责人”仍单独维护，不因任职自动替换。</p><p v-if="!managers.length" class="workflow-empty">该部门尚无任职记录。</p><article v-for="item in managers" :key="item.id" class="workflow-panel"><div class="workflow-between"><h2>{{ item.userName }} · {{ item.title==='HEAD'?'正职':'副职' }}</h2><span class="workflow-tag">{{ item.revokedAt?'已撤销':item.active?'当前有效':'非当前有效' }}</span></div><p>{{ item.effectiveFrom }} 至 {{ item.effectiveTo||'持续有效' }}{{ item.revokedAt?` · 撤销于 ${displayTime(item.revokedAt)}`:'' }}</p><button v-if="item.canRevoke" :disabled="busy" @click="open('revokeManager',item.id)">撤销任职</button></article></template><template v-if="tab==='grants'"><p class="workflow-note">跨部门范围独立保存，不跟随人员当前所属部门自动替换。管理员角色不自动获得业务事实审批权。</p><p v-if="!grants.length" class="workflow-empty">该人员尚无角色授权记录。</p><article v-for="item in grants" :key="item.id" class="workflow-panel"><div class="workflow-between"><h2>{{ roles[item.role] }} · {{ item.scopeType==='COMPANY'?'公司范围':item.departmentName }}</h2><span class="workflow-tag">{{ item.revokedAt?'已撤销':item.active?'当前有效':'非当前有效' }}</span></div><p>{{ item.effectiveFrom }} 至 {{ item.effectiveTo||'持续有效' }}{{ item.revokedAt?` · 撤销于 ${displayTime(item.revokedAt)}`:'' }}</p><button v-if="item.canRevoke" :disabled="busy" @click="open('revokeGrant',item.id)">撤销此范围授权</button></article></template><template v-if="tab==='history'&&history"><section class="workflow-panel"><h2>所属部门历史</h2><p v-for="item in history.departments" :key="item.id">{{ item.departmentName }} · {{ item.effectiveFrom }} 至 {{ item.effectiveTo||'持续有效' }}</p></section><section class="workflow-panel"><h2>职级历史</h2><p v-for="item in history.levels" :key="item.id">{{ ({JUNIOR:'初级',MIDDLE:'中级',SENIOR:'高级'} as Record<string,string>)[item.level]??item.level }} · {{ item.effectiveFrom }} 至 {{ item.effectiveTo||'持续有效' }}</p></section><section class="workflow-panel"><h2>填报适用区间</h2><p v-for="item in history.enrollments" :key="item.id">{{ item.effectiveFrom }} 至 {{ item.effectiveTo||'持续有效' }} · {{ item.voided?'已作废':'有效历史' }}</p></section></template><ModalShell v-if="modal" :busy="busy" @close="modal=''"><section class="workflow-dialog" role="dialog" aria-modal="true" aria-label="维护权限范围"><h2>{{ modal==='manager'?'登记部门任职':modal==='grant'?'登记角色范围':'撤销选定范围' }}</h2><p v-if="modal.startsWith('revoke')">撤销立即生效，原有效期与撤销时间保留。</p><form @submit.prevent="commit"><template v-if="modal==='manager'"><label>任职人员<select aria-label="任职人员" v-model="person" required :disabled="busy"><option value="">请选择</option><option v-for="u in users" :key="u.id" :value="u.id">{{ u.name }} / {{ u.employeeNo }}</option></select></label><label>职务<select aria-label="职务" v-model="title" :disabled="busy"><option value="HEAD">正职</option><option value="DEPUTY">副职</option></select></label></template><template v-if="modal==='grant'"><label>角色<select aria-label="角色" v-model="role" :disabled="busy" @change="changeRole"><option v-for="(label,key) in roles" :value="key" :key="key">{{ label }}</option></select></label><label>授权范围<select aria-label="授权范围" v-model="scopeType" :disabled="busy||role!=='LEADER'"><option value="COMPANY">全公司</option><option value="DEPARTMENT">指定部门及子部门</option></select></label><label v-if="scopeType==='DEPARTMENT'">授权部门<select aria-label="授权部门" v-model="scopeDepartment" required :disabled="busy"><option v-for="d in departments" :key="d.id" :value="d.id">{{ d.name }}</option></select></label></template><template v-if="['manager','grant'].includes(modal)"><label>开始日期<input v-model="from" type="date" required :disabled="busy" /></label><label>结束日期（不含）<input v-model="to" type="date" :min="from" :disabled="busy" /></label></template><label>业务理由<textarea v-model="reason" rows="3" required maxlength="1000" :disabled="busy" /></label><p v-if="error" class="workflow-error">{{ error }}</p><div class="workflow-actions"><button type="button" :disabled="busy" @click="modal=''">取消</button><button class="primary" type="submit" :disabled="busy">确认提交</button></div></form></section></ModalShell></div></template>
